 export function PokemonCardSkeleton({
   style,
 }: {
   style?: StyleProp<ViewStyle>;
 }) {
   const sweep = useSharedValue(-1);
   const sweepStyle = useAnimatedStyle(() => ({
     transform: [
       {
         translateX: interpolate(sweep.value, [-1, 1], [-180, 180]),
       },
     ],
   }));

