     return () => cancelAnimation(sweep);
   }, [sweep]);

   return (
     <ThemedView
       accessibilityLabel="Loading Pokémon"
       accessibilityRole="progressbar"
       style={[styles.card, style]}
     >
       <View style={styles.imageFrame}>
