 import { useLocalSearchParams, useRouter } from 'expo-router';
 import { useEffect, useMemo, useRef, useState } from 'react';
 import { useQueryClient } from '@tanstack/react-query';
 import { useTranslation } from 'react-i18next';
 import { Image } from 'expo-image';
 import { Pressable, ScrollView, StyleSheet, View } from 'react-native';

 import { ThemedText } from '@/components/themed-text';
 import { ThemedView } from '@/components/themed-view';
 import { Palette, Spacing } from '@/constants/theme';
 import {
   calculateDamage,
   calculateMaxHp,
   orderSides,
   type BattleSide,
 } from '@/lib/battle-engine';
 import { useBattlePokemon, useBattleTypeRelations } from '@/lib/queries';
 import { addBattleHistory } from '@/services/battle-history-db';

 export default function BattleFightScreen() {
   const { player = '', opponent = '' } = useLocalSearchParams<{
     player: string;
     opponent: string;
   }>();
   const router = useRouter();
   const { t } = useTranslation();
   const queryClient = useQueryClient();
   const playerQuery = useBattlePokemon(player);
   const opponentQuery = useBattlePokemon(opponent);
   const playerPokemon = playerQuery.data;
   const opponentPokemon = opponentQuery.data;
   const moveTypes = useMemo(
     () =>
       [...(playerPokemon?.moves ?? []), ...(opponentPokemon?.moves ?? [])].map(
         ({ type }) => type,
       ),
     [playerPokemon, opponentPokemon],
   );
   const relationsQuery = useBattleTypeRelations([...new Set(moveTypes)]);
   const [playerHpState, setPlayerHp] = useState<number | null>(null);
   const [opponentHpState, setOpponentHp] = useState<number | null>(null);
   const [turn, setTurn] = useState(0);
   const [winner, setWinner] = useState<BattleSide | null>(null);
   const [resolving, setResolving] = useState(false);
   const [log, setLog] = useState<string[]>([]);
   const saved = useRef(false);

   useEffect(() => {
     if (!winner || !playerPokemon || !opponentPokemon || saved.current) return;
     saved.current = true;
     void addBattleHistory({
       player: playerPokemon,
       opponent: opponentPokemon,
       winner,
       turns: turn,
     }).then(() => queryClient.invalidateQueries({ queryKey: ['battle-history'] }));
   }, [opponentPokemon, playerPokemon, queryClient, turn, winner]);

   if (
     playerQuery.isLoading ||
     opponentQuery.isLoading ||
     relationsQuery.isLoading ||
     !playerPokemon ||
     !opponentPokemon
   ) {
     return <StateView message={t('battleLoading')} />;
   }
   if (playerQuery.isError || opponentQuery.isError || relationsQuery.isError) {
     return (
       <StateView
         message={t('error')}
         action={t('tryAgain')}
         onAction={() => {
           void playerQuery.refetch();
           void opponentQuery.refetch();
           void relationsQuery.refetch();
         }}
       />
     );
   }
   const relations = relationsQuery.data ?? {};

   const playTurn = (moveIndex: number) => {
     if (resolving || winner) return;
     setResolving(true);
     const playerMove = playerPokemon.moves[moveIndex] ?? playerPokemon.moves[0];
     const opponentMove =
       opponentPokemon.moves[randomIndex(opponentPokemon.moves.length)];
     const actions = orderSides(playerPokemon, opponentPokemon, randomUnit()).map((side) => ({
       side,
       move: side === 'player' ? playerMove : opponentMove,
     }));
     let nextPlayerHp = playerHp;
     let nextOpponentHp = opponentHp;
     const messages: string[] = [];
     for (const action of actions) {
       if (nextPlayerHp <= 0 || nextOpponentHp <= 0) break;
       const attacker = action.side === 'player' ? playerPokemon : opponentPokemon;
       const defender = action.side === 'player' ? opponentPokemon : playerPokemon;
       const result = calculateDamage(attacker, defender, action.move, relations);
       if (!result.hit) {
         messages.push(`${attacker.name} ${t('battleMissed')} ${action.move.name}.`);
         continue;
       }
       if (action.side === 'player') {
         nextOpponentHp = Math.max(0, nextOpponentHp - result.damage);
       } else {
         nextPlayerHp = Math.max(0, nextPlayerHp - result.damage);
       }
       const outcome =
         result.effectiveness === 'super'
           ? t('battleSuperEffective')
           : result.effectiveness === 'notVery'
             ? t('battleNotVeryEffective')
             : result.effectiveness === 'none'
               ? t('battleNoEffect')
               : '';
       messages.push(
         `${attacker.name} ${t('battleUsed')} ${action.move.name}: ${result.damage} ${t('battleDamage')}${outcome ? ` (${outcome})` : ''}.`,
       );
     }
     const nextWinner = nextPlayerHp <= 0 ? 'opponent' : nextOpponentHp <= 0 ? 'player' : null;
     setPlayerHp(nextPlayerHp);
     setOpponentHp(nextOpponentHp);
     setTurn((current) => current + 1);
     setLog((current) => [...messages, ...current]);
     setWinner(nextWinner);
     setResolving(false);
   };

   return (
     <ThemedView style={styles.screen}>
       <ScrollView contentContainerStyle={styles.content}>
         <View style={styles.header}>
           <ThemedText type="subtitle" style={styles.title}>{t('battleFight')}</ThemedText>
           <Pressable onPress={() => router.replace('/battle')} accessibilityRole="button">
             <ThemedText style={styles.link}>{t('battleNew')}</ThemedText>
           </Pressable>
         </View>
         <BattleCard pokemon={opponentPokemon} hp={opponentHp} />
         <ThemedText style={styles.vs}>VS</ThemedText>
         <BattleCard pokemon={playerPokemon} hp={playerHp} />
         {winner && (
           <View style={styles.winner}>
             <ThemedText type="subtitle" style={styles.winnerText}>
               {winner === 'player' ? t('battleYouWin') : t('battleYouLose')}
             </ThemedText>
             <ThemedText style={styles.winnerText}>{t('battleTurns')}: {turn}</ThemedText>
           </View>
         )}
         {!winner && (
           <View style={styles.moves}>
             <ThemedText type="smallBold">{t('battleChooseMove')}</ThemedText>
             {playerPokemon.moves.map((move, index) => (
               <Pressable
                 key={`${move.name}-${index}`}
                 accessibilityRole="button"
                 accessibilityLabel={`${move.name}, ${move.type}`}
                 disabled={resolving}
                 onPress={() => playTurn(index)}
                 style={[styles.move, resolving && styles.disabled]}
               >
                 <ThemedText style={styles.moveName}>{move.name}</ThemedText>
                 <ThemedText style={styles.moveMeta}>
                   {move.type} · {move.power ?? 0} power · {move.accuracy ?? 100}% accuracy
                 </ThemedText>
               </Pressable>
             ))}
           </View>
         )}
         <View style={styles.log}>
           <ThemedText type="smallBold">{t('battleLog')}</ThemedText>
           {log.length === 0 ? (
             <ThemedText themeColor="textSecondary">{t('battleLogEmpty')}</ThemedText>
           ) : (
             log.map((entry, index) => <ThemedText key={`${entry}-${index}`}>{entry}</ThemedText>)
           )}
         </View>
       </ScrollView>
     </ThemedView>

