         )}
         <ThemedView type="container" style={styles.log}>
           <ThemedText type="smallBold">{t("battleLog")}</ThemedText>
           {log.length === 0 ? (
             <ThemedText themeColor="textSecondary">
               {t("battleLogEmpty")}
             </ThemedText>
           ) : (
             log.map((entry, index) => (
               <ThemedText key={`${entry}-${index}`}>{entry}</ThemedText>
