 }

 function BattleCard({
   pokemon,
   hp,
 }: {
   pokemon: NonNullable<ReturnType<typeof useBattlePokemon>["data"]>;
   hp: number;
 }) {
   const maxHp = calculateMaxHp(pokemon);
   return (
     <View style={styles.card}>
       <Image source={pokemon.image} style={styles.image} contentFit="contain" />
       <View style={styles.cardText}>
         <ThemedText type="subtitle" style={styles.cardName}>
           {pokemon.name}
         </ThemedText>
         <ThemedText style={styles.hp}>
           {hp} / {maxHp} HP
         </ThemedText>
         <View style={styles.track}>
           <View
             style={[
               styles.fill,
               { width: `${Math.max(0, (hp / maxHp) * 100)}%` },
             ]}
           />
         </View>
       </View>
     </View>
   );
 }

 function StateView({
   message,
   action,
   onAction,
 }: {
   message: string;
   action?: string;
   onAction?: () => void;
 }) {
   return (
     <ThemedView style={styles.state}>
       <ThemedText type="subtitle">{message}</ThemedText>
       {action && onAction && (
         <Pressable
           onPress={onAction}
           style={styles.startButton}
           accessibilityRole="button"
         >
           <ThemedText style={styles.winnerText}>{action}</ThemedText>
         </Pressable>
       )}
     </ThemedView>
   );
 }

